CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

// Fused cross-entropy kernel: one block per row, 256 threads
// Each thread handles multiple class indices (stride = blockDim.x)
// Computes: loss_i = log(sum_j exp(x_ij - max_i)) + max_i - x_i[target_i]

#define BLOCK_SIZE 256
#define WARP_SIZE 32

__device__ __forceinline__ float warp_reduce_max(float val) {
    for (int offset = WARP_SIZE/2; offset > 0; offset >>= 1)
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = WARP_SIZE/2; offset > 0; offset >>= 1)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void cross_entropy_kernel(
    const float* __restrict__ logits,
    const int64_t* __restrict__ targets,
    float* __restrict__ losses,
    int N,
    int C
) {
    int row = blockIdx.x;
    if (row >= N) return;

    const float* row_logits = logits + row * C;
    int64_t target = targets[row];

    __shared__ float smem[BLOCK_SIZE / WARP_SIZE];
    int tid = threadIdx.x;
    int num_warps = BLOCK_SIZE / WARP_SIZE;
    int warp_id = tid / WARP_SIZE;
    int lane_id = tid % WARP_SIZE;

    // Pass 1: find row max
    float local_max = -FLT_MAX;
    for (int j = tid; j < C; j += BLOCK_SIZE) {
        float v = row_logits[j];
        if (v > local_max) local_max = v;
    }
    local_max = warp_reduce_max(local_max);
    if (lane_id == 0) smem[warp_id] = local_max;
    __syncthreads();
    if (tid < num_warps) {
        float v = smem[tid];
        v = warp_reduce_max(v);
        if (tid == 0) smem[0] = v;
    }
    __syncthreads();
    float row_max = smem[0];

    // Pass 2: compute exp-sum and gather target logit
    float local_sum = 0.0f;
    for (int j = tid; j < C; j += BLOCK_SIZE) {
        local_sum += expf(row_logits[j] - row_max);
    }
    local_sum = warp_reduce_sum(local_sum);
    if (lane_id == 0) smem[warp_id] = local_sum;
    __syncthreads();
    if (tid < num_warps) {
        float v = smem[tid];
        v = warp_reduce_sum(v);
        if (tid == 0) smem[0] = v;
    }
    __syncthreads();
    float row_sum = smem[0];

    if (tid == 0) {
        float target_logit = row_logits[target];
        losses[row] = logf(row_sum) + row_max - target_logit;
    }
}

torch::Tensor cross_entropy_forward(
    torch::Tensor predictions,
    torch::Tensor targets
) {
    TORCH_CHECK(predictions.is_cuda(), "predictions must be CUDA tensor");
    TORCH_CHECK(targets.is_cuda(), "targets must be CUDA tensor");
    TORCH_CHECK(predictions.is_contiguous(), "predictions must be contiguous");
    TORCH_CHECK(targets.is_contiguous(), "targets must be contiguous");
    TORCH_CHECK(predictions.dtype() == torch::kFloat32, "predictions must be float32");
    TORCH_CHECK(targets.dtype() == torch::kInt64, "targets must be int64");
    TORCH_CHECK(predictions.dim() == 2, "predictions must be 2D");
    TORCH_CHECK(targets.dim() == 1, "targets must be 1D");

    int N = predictions.size(0);
    int C = predictions.size(1);
    TORCH_CHECK(targets.size(0) == N, "targets size mismatch");

    auto losses = torch::empty({N}, predictions.options());

    dim3 grid(N);
    dim3 block(BLOCK_SIZE);
    cross_entropy_kernel<<<grid, block>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<int64_t>(),
        losses.data_ptr<float>(),
        N, C
    );

    return losses.mean();
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        A model that computes Cross Entropy Loss for multi-class classification tasks.

        Parameters:
            None
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        # <<<END_IMPROVE>>>

    def forward(self, predictions, targets):
        # <<<IMPROVE:forward_stmt_1>>>
        if (predictions.is_cuda and targets.is_cuda and
                predictions.dtype == torch.float32 and targets.dtype == torch.int64 and
                predictions.dim() == 2 and targets.dim() == 1 and
                predictions.is_contiguous() and targets.is_contiguous() and
                predictions.size(0) == targets.size(0)):
            return _stark_get_extension().cross_entropy_forward(predictions, targets)
        return torch.nn.functional.cross_entropy(predictions, targets)
        # <<<END_IMPROVE>>>

